<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {request} from './service';
const contract=ref<any>(null),error=ref('');
const groups=[
 {title:'公开页面',detail:'无需登录，仅返回可公开内容。',items:[['GET','/api/public/bootstrap','站点、片头、导航和页面配置'],['GET','/api/public/home','按配置顺序读取首页模块'],['GET','/api/public/catalog/posts','文章摘要分页，支持 q、category、tag'],['GET','/api/public/catalog/anime','分页海报墙，支持 season、weekday、q']]},
 {title:'空间与素材',detail:'仅管理员会话可访问。',items:[['GET','/api/private/overview','创作、审核、任务与邮件配置状态'],['GET','/api/private/catalog/records/{kind}','按 q、subtype 分页检索记录'],['GET','/api/private/catalog/documents','文档摘要，支持 q 和 category'],['GET','/api/private/documents/{id}','按需加载文档全文'],['GET','/api/private/media','按 source、q 查找素材；不自动公开上传'],['GET','/api/private/api-contract','下载完整接口和记录字段契约']]},
 {title:'自动化',detail:'列表轮询只传摘要，选中后读取详情。',items:[['GET','/api/private/automation?compact=true','任务、模板与最近运行摘要'],['GET','/api/private/automation/runs','分页记录，支持 state、flowId'],['GET','/api/private/automation/runs/{id}','单次运行完整结果'],['POST','/api/v1/automation/results','本地 AI 使用 automation:submit 凭证提交结果']]}
];
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(contract.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='frontend-api-contract.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
onMounted(async()=>{try{contract.value=await request('/api/private/api-contract');}catch(e:any){error.value=e.message;}});
</script>
<template><section class="api-page"><header><span class="space-eyebrow">BUILD YOUR NEXT FRONTEND</span><h1>内容与设计，留好连接。</h1><p>后续页面可以独立改版。公开页面使用公开投影；空间保留管理员权限，AI 接入使用独立的最小权限凭证。</p><el-button :disabled="!contract" @click="download">下载接口契约 JSON</el-button><RouterLink to="/access-tokens">管理 AI 访问凭证 ↗</RouterLink></header><p v-if="error" role="alert">{{error}}</p><div class="rules"><article><h2>分页与搜索</h2><p>page 从 1 开始，pageSize 最大 100。响应统一包含 items、total、page、pageSize、hasMore。</p></article><article><h2>保存与冲突</h2><p>沿用现有 PUT / DELETE 的 version。遇到 409 请提示重新读取，避免覆盖另一处修改。</p></article><article><h2>图片与权限</h2><p>使用服务端返回的素材 URL。私有素材不会因查询而公开；前端不要拼接上传路径或保存 Token。</p></article></div><section v-for="group in groups" :key="group.title" class="api-group"><h2>{{group.title}}</h2><p>{{group.detail}}</p><article v-for="[method,path,detail] in group.items" :key="path"><b>{{method}}</b><code>{{path}}</code><span>{{detail}}</span></article></section><footer>本地详细说明：docs/API-frontend-foundation.md。旧接口继续兼容，新页面优先使用这里的分页与聚合接口。</footer></section></template>
<style scoped>.api-page{max-width:1160px;margin:auto}.api-page header{padding:12px 0 28px;border-bottom:1px solid var(--studio-line)}.api-page h1{font-size:30px;margin:15px 0}.api-page p,.api-page footer{font-size:13px;color:var(--studio-muted);line-height:1.9}.api-page header a{margin-left:20px;font-size:12px}.rules{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:24px 0}.rules article{padding:22px;border:1px solid var(--studio-line);background:var(--studio-panel);border-radius:10px}.api-page h2{font-size:18px}.api-group{padding:20px 0;border-bottom:1px solid var(--studio-line)}.api-group article{display:grid;grid-template-columns:55px minmax(260px,1fr) 1fr;gap:15px;padding:16px 0;border-top:1px solid var(--studio-line);align-items:start}.api-group b{font:11px/1.8 monospace;color:var(--studio-accent,#8273a6)}.api-group code{font-size:12px;overflow-wrap:anywhere}.api-group span{font-size:12px;color:var(--studio-muted)}footer{margin:24px 0}@media(max-width:750px){.rules{grid-template-columns:1fr}.api-group article{grid-template-columns:55px minmax(0,1fr)}.api-group span{grid-column:2}.api-page h1{font-size:25px}}</style>
